// 配置外置：行为由外部配置决定，而不是散落在代码里的常量
function makeService(config) {
  return {
    timeout: config.timeoutMs ?? 3000,
    retries: config.retries ?? 0,
    endpoint: config.endpoint,
    describe() {
      return `${this.endpoint} (timeout=${this.timeout}, retries=${this.retries})`;
    },
  };
}

const s = makeService({ endpoint: "https://api.x", retries: 2 });
console.log(s.describe());
console.log(s.timeout); // 没传则使用默认值
